<?php
require_once __DIR__ . '/includes/auth.php';
require_admin();
$pageTitle='Laporan';$activePage='laporan';$pdo=db();$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');
$stmt=$pdo->prepare("SELECT COUNT(*) jumlah_transaksi,COALESCE(SUM(total),0) omzet,COALESCE(SUM(bayar-total),0) kembalian FROM app_transaksi WHERE status='paid' AND DATE(paid_at) BETWEEN ? AND ?");$stmt->execute([$from,$to]);$summary=$stmt->fetch();
$stmt=$pdo->prepare("SELECT DATE(paid_at) tanggal,COUNT(*) jumlah,COALESCE(SUM(total),0) omzet FROM app_transaksi WHERE status='paid' AND DATE(paid_at) BETWEEN ? AND ? GROUP BY DATE(paid_at) ORDER BY tanggal DESC");$stmt->execute([$from,$to]);$daily=$stmt->fetchAll();
$stmt=$pdo->prepare("SELECT b.nama_barang,SUM(d.qty) qty,SUM(d.subtotal) omzet FROM app_detail_transaksi d JOIN app_transaksi t ON t.id=d.transaksi_id JOIN barang b ON b.id=d.barang_id WHERE t.status='paid' AND DATE(t.paid_at) BETWEEN ? AND ? GROUP BY d.barang_id,b.nama_barang ORDER BY omzet DESC LIMIT 10");$stmt->execute([$from,$to]);$products=$stmt->fetchAll();
include __DIR__.'/includes/header.php';
?><section class="card no-print"><div class="section-head"><div><h2>Filter laporan</h2></div><button class="btn btn-light" onclick="window.print()">Cetak laporan</button></div><form class="toolbar"><input class="input" type="date" name="from" value="<?= e($from) ?>"><span class="muted">sampai</span><input class="input" type="date" name="to" value="<?= e($to) ?>"><button class="btn btn-primary">Tampilkan</button></form></section><div class="grid stats-grid" style="margin-top:18px"><div class="card stat-card"><div class="label">Total omzet</div><div class="number"><?= money($summary['omzet']) ?></div></div><div class="card stat-card green"><div class="label">Jumlah transaksi</div><div class="number"><?= e($summary['jumlah_transaksi']) ?></div></div><div class="card stat-card orange"><div class="label">Rata-rata transaksi</div><div class="number"><?= money($summary['jumlah_transaksi']?(float)$summary['omzet']/$summary['jumlah_transaksi']:0) ?></div></div><div class="card stat-card red"><div class="label">Kembalian tercatat</div><div class="number"><?= money($summary['kembalian']) ?></div></div></div><div class="grid two-col"><section class="card"><div class="section-head"><h2>Penjualan per hari</h2><span class="muted small"><?= e($from) ?> — <?= e($to) ?></span></div><div class="table-wrap"><table class="table"><thead><tr><th>Tanggal</th><th>Transaksi</th><th>Omzet</th></tr></thead><tbody><?php foreach($daily as $row): ?><tr><td><?= e(date('d F Y',strtotime($row['tanggal']))) ?></td><td><?= e($row['jumlah']) ?></td><td class="amount"><?= money($row['omzet']) ?></td></tr><?php endforeach;if(!$daily): ?><tr><td colspan="3" class="empty">Tidak ada data pada rentang tanggal ini.</td></tr><?php endif; ?></tbody></table></div></section><section class="card"><div class="section-head"><h2>Produk terlaris</h2></div><div class="table-wrap"><table class="table"><thead><tr><th>Barang</th><th>Qty</th><th>Omzet</th></tr></thead><tbody><?php foreach($products as $row): ?><tr><td><?= e($row['nama_barang']) ?></td><td><?= e($row['qty']) ?></td><td class="amount"><?= money($row['omzet']) ?></td></tr><?php endforeach;if(!$products): ?><tr><td colspan="3" class="empty">Belum ada produk terjual.</td></tr><?php endif; ?></tbody></table></div></section></div><?php include __DIR__.'/includes/footer.php'; ?>
